    // Helper function to convert an ASCII uppercase letter to lowercase.
    // If char is between 'A' and 'Z', convert to lowercase.
    // Otherwise, return the char unchanged.
    fn to_ascii_lowercase(c: char) -> char {
        if c >= 'A' && c <= 'Z' {
            ((c as u8) + 32) as char // 'A' to 'a': add 32
        } else {
            c
        }
    }

